def decode_reservation(payload):
    # OWN v1synthetic inventory units,not money or a live account.
    required={"schema","request_id","sku","quantity"}
    if type(payload) is not dict or not required<=set(payload) or not set(payload)<=required|{"trace_id"}:
        raise ValueError("unsupported request fields")
    if type(payload["schema"]) is not int or payload["schema"]!=1:raise ValueError("unsupported request schema")
    def identifier(value):
        return type(value) is str and 1<=len(value)<=32 and all(c in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-" for c in value)
    if not identifier(payload["request_id"]):raise ValueError("invalid request id")
    if "trace_id" in payload and not identifier(payload["trace_id"]):raise ValueError("invalid trace id")
    if type(payload["sku"]) is not str or payload["sku"] not in ("A","B"):raise ValueError("unsupported sku")
    if type(payload["quantity"]) is not int or not 1<=payload["quantity"]<=10:raise ValueError("invalid reservation quantity")
    return (1,payload["request_id"],payload["sku"],payload["quantity"])

import json,sqlite3

def new_store():
    db=sqlite3.connect(":memory:",autocommit=sqlite3.LEGACY_TRANSACTION_CONTROL,isolation_level=None)
    db.execute("CREATE TABLE inventory(sku TEXT PRIMARY KEY,units INTEGER NOT NULL CHECK(units>=0))")
    db.execute("CREATE TABLE requests(id TEXT PRIMARY KEY,sku TEXT NOT NULL,quantity INTEGER NOT NULL,response TEXT NOT NULL)")
    db.executemany("INSERT INTO inventory VALUES(?,?)",[("A",10),("B",5)])
    return db

def reserve(db,payload,failpoint=None):
    _,request_id,sku,quantity=decode_reservation(payload)
    if failpoint not in (None,"after-stock","after-response","after-commit"):raise ValueError("invalid failpoint")
    db.execute("BEGIN")
    try:
        cached=db.execute("SELECT sku,quantity,response FROM requests WHERE id=?",(request_id,)).fetchone()
        if cached is not None:
            if cached[:2]!=(sku,quantity):raise ValueError("idempotency key conflict")
            response=json.loads(cached[2]);db.execute("COMMIT");return response
        changed=db.execute("UPDATE inventory SET units=units-? WHERE sku=? AND units>=?",(quantity,sku,quantity)).rowcount
        if changed!=1:raise ValueError("insufficient synthetic inventory")
        if failpoint=="after-stock":raise RuntimeError("injected after stock")
        response={"schema":1,"request_id":request_id,"status":"reserved","sku":sku,"quantity":quantity}
        raw=json.dumps(response,sort_keys=True,separators=(",",":"))
        db.execute("INSERT INTO requests VALUES(?,?,?,?)",(request_id,sku,quantity,raw))
        if failpoint=="after-response":raise RuntimeError("injected after response")
        db.execute("COMMIT")
        if failpoint=="after-commit":raise RuntimeError("injected lost acknowledgment")
        return response
    except Exception:
        if db.in_transaction:db.execute("ROLLBACK")
        raise

def state(db):
    return tuple(db.execute("SELECT sku,units FROM inventory ORDER BY sku")),tuple(db.execute("SELECT id,sku,quantity FROM requests ORDER BY id"))

request={"schema":1,"request_id":"r1","sku":"A","quantity":3}
db=new_store()
try:
    before=state(db)
    try:reserve(db,request,"after-stock")
    except RuntimeError as error:print(error)
    print("rollback",state(db)==before)
    first=reserve(db,request)
    print(first["status"],state(db)[0])
    print("replay",reserve(db,{**request,"trace_id":"retry"})==first,state(db)[0])
    try:reserve(db,{**request,"quantity":2})
    except ValueError as error:print(error)
    r2={**request,"request_id":"r2","quantity":2}
    try:reserve(db,r2,"after-commit")
    except RuntimeError as error:print(error)
    print("recover",reserve(db,r2)["quantity"],state(db))
finally:db.close()
